S = "Hakeem Force Academy"
QS = [
(S, "In which Islamic month did the Battle (Ghazwa) of Uhad take place?", ["Ramadan", "Shawwal", "Muharram", "Dhul Qadah"], 1, "The Battle of Uhad was fought on 7 Shawwal 3 AH near Mount Uhad close to Madina.", "The Battle of Badr was fought in the previous year, in Ramadan 2 AH.", 1),
(S, "In which Islamic month did the tragedy of Karbala take place?", ["Rajab", "Safar", "Muharram", "Rabi ul Awwal"], 2, "Imam Hussain (RA) was martyred at Karbala on 10 Muharram 61 AH, the day of Ashura.", "The year of the event, 61 AH, fell during the rule of Yazid.", 2),
(S, "In which Islamic month is Eid ul Fitr celebrated?", ["Ramadan", "Dhul Hijjah", "Shawwal", "Rajab"], 2, "Eid ul Fitr is celebrated on 1 Shawwal after the month of fasting ends.", "Eid ul Fitr was first celebrated in 2 AH.", 1),
(S, "In which Islamic month is Laylat ul Qadr (the Night of Power)?", ["Shaban", "Ramadan", "Rabi ul Awwal", "Shawwal"], 1, "Laylat ul Qadr is sought in the last ten nights of Ramadan, especially the odd nights.", "Surah Al-Qadr is devoted to this night, which is described as better than a thousand months.", 1),
(S, "In which Islamic month was the Ghazwa (Battle) of Badr fought?", ["Ramadan", "Shawwal", "Muharram", "Rajab"], 0, "The Battle of Badr took place on 17 Ramadan 2 AH.", "It is called Yaum ul Furqan, the day of distinction between truth and falsehood.", 2),
(S, "In which mountain range of Pakistan is Tirich Mir located?", ["Karakoram", "Hindu Kush", "Himalaya", "Sulaiman"], 1, "Tirich Mir lies in Chitral district of Khyber Pakhtunkhwa, in the Hindu Kush range.", "At about 7,708 metres it is the highest peak of the Hindu Kush.", 1),
(S, "In which Nabawi year did the Year of Grief (Aam ul Huzn) occur?", ["7th Nabawi", "10th Nabawi", "13th Nabawi", "5th Nabawi"], 1, "In the 10th year of prophethood both Hazrat Abu Talib and Hazrat Khadijah (RA) passed away within a short time.", "The year corresponds to about 619 CE.", 1),
(S, "In which province is Chagai district situated?", ["Sindh", "Khyber Pakhtunkhwa", "Punjab", "Balochistan"], 3, "Chagai is a district in the west of Balochistan bordering Afghanistan and Iran.", "Pakistan conducted its nuclear tests in the Ras Koh hills of Chagai in May 1998.", 1),
(S, "In which province is the Gomal Zam Dam located?", ["Balochistan", "Punjab", "Khyber Pakhtunkhwa", "Sindh"], 2, "Gomal Zam Dam is built on the Gomal River in South Waziristan, in Khyber Pakhtunkhwa.", "It is a multipurpose dam completed in 2013.", 1),
(S, "In which province is Ghotki located?", ["Punjab", "Balochistan", "Khyber Pakhtunkhwa", "Sindh"], 3, "Ghotki is a district in northern Sindh on the border with Punjab.", "Its main city is Mirpur Mathelo.", 1),
(S, "In which province is Kundol (Kundal) Lake situated?", ["Khyber Pakhtunkhwa", "Gilgit-Baltistan", "Punjab", "Balochistan"], 0, "Kundol Lake lies in the upper Swat valley near Kalam in Khyber Pakhtunkhwa.", "Swat is famous for lakes such as Mahodand and Kundol.", 1),
(S, "In which part of Pakistan is Mirpur located?", ["Azad Jammu and Kashmir", "Punjab", "Sindh", "Gilgit-Baltistan"], 0, "Mirpur is a city and district in Azad Jammu and Kashmir (the question is often worded as province, though AJK is not a province).", "Mangla Dam is built near Mirpur on the Jhelum River.", 1),
(S, "In which province is Narowal district located?", ["Khyber Pakhtunkhwa", "Sindh", "Punjab", "Balochistan"], 2, "Narowal is a district in northeastern Punjab near the Indian border.", "Narowal was made a separate district in 1991.", 1),
(S, "In which province does the Soan River flow?", ["Punjab", "Sindh", "Balochistan", "Khyber Pakhtunkhwa"], 0, "The Soan rises in the Murree hills and flows through the Potohar plateau of Punjab (Rawalpindi area) to join the Indus.", "The Soan valley is one of the oldest sites of early human tools in South Asia.", 1),
(S, "On which river are the Victoria Falls situated?", ["Nile", "Congo", "Zambezi", "Niger"], 2, "Victoria Falls lies on the Zambezi River on the border of Zambia and Zimbabwe.", "Its local name is Mosi-oa-Tunya, the smoke that thunders.", 1),
(S, "In which Surah does the phrase Bismillah occur twice (once at the start and once within a verse)?", ["Surah Al-Naml", "Surah Al-Baqarah", "Surah Yusuf", "Surah Al-Ikhlas"], 0, "In Surah Al-Naml the Bismillah appears at the start and again in verse 30 in the letter of Prophet Sulaiman (AS) to the Queen of Sheba.", "Surah At-Tawbah is the only surah without Bismillah at its start.", 1),
(S, "In which Surah was the first revelation to the Holy Prophet (SAW) revealed?", ["Surah Al-Fatiha", "Surah Al-Muddaththir", "Surah Al-Alaq", "Surah Al-Muzzammil"], 2, "The first five verses of Surah Al-Alaq were revealed in the cave of Hira, beginning with Iqra.", "The revelation came in Ramadan when the Prophet (SAW) was 40 years old.", 1),
(S, "In which year did Britain annex Sindh?", ["1843", "1839", "1849", "1857"], 0, "Sir Charles Napier defeated the Talpur Mirs at the Battle of Miani in 1843 and Sindh was annexed.", "Punjab was annexed later, in 1849.", 1),
(S, "In which year did Hazrat Hind (wife of Abu Sufyan) embrace Islam?", ["6 AH", "8 AH", "2 AH", "10 AH"], 1, "She accepted Islam at the Conquest of Makkah in 8 AH (630 CE).", "She was the mother of Hazrat Muawiyah (RA).", 1),
(S, "In which year did Malala Yousafzai receive the Nobel Peace Prize?", ["2012", "2013", "2014", "2015"], 2, "Malala was awarded the Nobel Peace Prize in 2014, jointly with Kailash Satyarthi.", "At age 17 she became the youngest Nobel laureate ever.", 1),
(S, "In which year did Pakistan become a full member of the Shanghai Cooperation Organisation (SCO)?", ["2005", "2010", "2017", "2021"], 2, "Pakistan and India were admitted as full members at the SCO summit in Astana in June 2017.", "Pakistan had been an observer since 2005.", 1),
]
